save(44,dict(paragraphs=['Rajorshi Patranabis is a multilingual poet, translator and editor whose writing moves between English and Bengali and between several poetic forms. His collections include The Last Drop of Your Tears and Checklist Anomaly, both exploring five-line poetry. He has also translated Sutapa Chakraborty’s The Hornet’s Trail into English. In an interview with Borderless, he describes his interest in haiku and haibun as part of the path towards these shorter forms.','“Crippling assortment” compresses the struggle to write and believe into a sequence of unsettled images. Words become clouded prisms; intuition and contradiction pull against one another. Its brief final stanza leaves faith still labouring towards belief, giving the poem an unresolved, questioning close.'],sources=[source('Transcendent Zero Press — The Hornet’s Trail','https://transcendentzeropress.org/the-hornets-trail-by-sutapa-chakraborty-trans-rajorshi-patranabis/','Publisher identifies Rajorshi as translator of Sutapa Chakraborty and provides matching multilingual poet biography, forms and collection titles.'),source('Borderless — interview with Rajorshi Patranabis (2024)','https://borderlessjournal.com/2024/03/14/checklist-anomaly-a-wiccans-journey-of-exploration/','Opened author interview confirms Checklist Anomaly, The Last Drop of Your Tears and progression from haiku/haibun to five-line forms.')],books=[dict(title='The Hornet’s Trail',detail='Poems by Sutapa Chakraborty · English translation by Rajorshi Patranabis · Transcendent Zero Press',url='https://transcendentzeropress.org/the-hornets-trail-by-sutapa-chakraborty-trans-rajorshi-patranabis/'),dict(title='Checklist Anomaly',detail='Poetry · Hawakal · Author interview',url='https://borderlessjournal.com/2024/03/14/checklist-anomaly-a-wiccans-journey-of-exploration/')],identity_match='Uncommon full name, multilingual writing, distinctive sequence of poetic forms and Wiccan self-description match captured contributor biography, publisher translator biography and direct interview. Not a name-only match.',poems_read=[dict(id=27,title='Crippling assortment',coverage='Full English original, all four stanzas and thirteen lines.',basis='Clouded words/prisms, thwarted expression, intuitive hunch and contradictory faith; interpretive close reading, not psychological biography.')],limitations=['Claims to world-first or first-in-India status for poetic forms omitted; not independently established.','Book totals vary by date and are omitted.','Publisher page’s January 2025 book-fair date not repeated.','Captured older title spelling Pallette preserved; no source biography rewritten.'],research_leads=[dict(url='https://penprints.in/wp-content/uploads/2025/01/catalouge-2025_final.pdf',finding='Search index lists Soliloquy by Rajorshi Patranabis as Kafir; direct open returned verification screen. Not needed for current narrative.')],next_action='Independent author/editor review of narrative and preferred bibliography.'))
